import {quoteDivineStone,divineStoneBalance} from './divine-stone.js';
import {equipmentDisplayName} from './equipment-display-name.js';
import {equipmentIcon} from './equipment-art.js';
import {SLOTS,SLOTNAME} from './engine.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reason={ 'already-divine':'这件装备已经获得神赐。','no-stone':'天神之石不足。','busy':'确认后会先等待战斗结束并暂停远征。','pending-reforge':'请先处理这件装备的待选重铸结果。','invalid-state':'当前不能进行神赐。','missing-item':'请选择一件装备。'};
export function renderDivineStoneForge(s,{slot=null,itemId=null,notice=''}={}){
 const it=s.inventory.find(i=>i.id===itemId),q=it?quoteDivineStone(s,itemId):null,stock=divineStoneBalance(s),eligible=!!it&&!it.divine&&stock>0&&s.pendingReforge?.itemId!==it.id;
 return `<section class="equipmentWorkshop divineStoneForge"><div class="workshopTitle"><div><span class="eyebrow">THE FORGE</span><h2>装备神赐</h2><strong>天神之石 ×${stock}</strong><p>首次通过异界第50、100、150…层获得，每个节点仅一次。</p></div></div><div class="workshopGrid"><div class="workshopOwned"><h3>选择部位</h3><nav class="forgeSlotPicker">${SLOTS.map(k=>`<button data-divine-slot="${k}" aria-pressed="${slot===k}">${SLOTNAME[k]} <small>${s.inventory.filter(i=>i.slot===k).length}</small></button>`).join('')}</nav><h3>选择装备</h3><div class="workshopItemGrid">${s.inventory.filter(i=>i.slot===slot).map(i=>`<button class="workshopItem ${i.set?'setFrame':''} ${i.id===itemId?'selected':''}" data-divine-item="${esc(i.id)}" title="${esc(equipmentDisplayName(i))}">${equipmentIcon(i,{size:32})}${i.divine?'<small>神赐</small>':''}</button>`).join('')}</div></div><div class="workshopBench">${it?`<div class="workshopItemHeading"><h3>${esc(equipmentDisplayName(it))}</h3><small>Lv.${it.level}${it.divine?' · 已神赐':''}</small></div><p>强化后的基础属性与普通词条翻倍；特殊词条的主要数值翻倍，传说专属效果不变。</p><p>保留词条、成长进度、强化和套装，不会重新随机。</p>${q?.ok?`<div class="workshopBasePreview">${[['atk','攻击'],['armor','护甲'],['hp','生命']].map(([key,label])=>`<p>${label} ${q.before[key]} → <strong>${q.after[key]}</strong></p>`).join('')}</div>`:''}<button class="primary" data-divine-apply="${esc(it.id)}" ${eligible?'':'disabled'}>${it.divine?'已获得神赐':'消耗1颗天神之石 · 必定神赐'}</button>${q&&!q.ok?`<p class="subtleText">${reason[q.reason]??'暂时无法神赐。'}</p>`:''}`:'<p>先选择部位，再选择一件已有装备。</p>'}<p class="workshopSmall">不消耗金币；已神赐装备不能重复使用。保存失败不消耗石头。</p>${notice?`<p role="status">${esc(notice)}</p>`:''}</div></div></section>`;
}
